import os
import re
from copy import deepcopy
from auto_config.generator.utils.logger import logger
from auto_config.generator.utils.telemetry import tl_update


class PddbParser:

    PERL2PY = {
        # %PDDB = (
        r"^%(\S+) = \($": r"'\1': {",
        # MOC => {
        r"^(\s+)([a-zA-Z_0-9]+)\s+=> \{$": r"\1'\2': {",
        # 'wtrans'   =>  sub { return shift },
        r"^(\s+)'([a-zA-Z_0-9\.]+)'\s+=>\s+sub\s+\{(.*)\},$": r"\1'\2': '\3',",
        # 'struct'   => {
        r"^(\s+)'struct'\s+=>\s+\{$": r"\1'struct': {",
        # 'struct'   => '',
        r"^(\s+)'struct'\s+=>\s+'',$": r"",
        # 'required'   => 'Mandatory',
        r"^(\s+)'required'\s+=>\s+'Mandatory',$": r"\1'required': True,",
        # 'required'   => 'other',
        r"^(\s+)'required'\s+=>\s+'.*',$": r"\1'required': False,",
        # 'otherAttr' => {
        r"^(\s+)'([a-zA-Z_0-9]+)'\s+=> \{$": r"\1'\2': {",
        # 'otherAttr' => 'Some value',
        r"^(\s+)'([a-zA-Z_0-9\.]+)'\s+=> '(.*)',$": r"\1'\2': '\3',",
        # MOC => 'ADAPT:MOC',
        r"^(\s+)([a-zA-Z_0-9]+)\s+=> '(.*)',$": r"\1'\2': '\3',",

        # ENDings
        r"^(\s+)\},": r"\1},",
        r"^\);$": "},",
        r"^1;$": "",
    }

    def __init__(self):
        self.parsed_pddb = {}
        self.perl2py_comp = {re.compile(k): v for k, v in self.PERL2PY.items()}
        self.CHECK_RANGE = {
            "Number": self._check_range_number,
            "String": self._check_range_string,
            "Boolean": self._check_range_boolean,
            "Bitmask": self._check_range_bitmask,
            "Enumeration": self._check_range_enumeration,
        }
        self.fail_on_error = os.environ.get("AC_FAIL_ON_ERROR")

    def _transform_perl_to_py(self, filepath):
        lines = []
        with open(filepath, mode='r', encoding='utf-8') as pddb_file:
            for i, line in enumerate(pddb_file):
                for patt, sub in self.perl2py_comp.items():
                    srch = re.search(patt, line)
                    if srch:
                        lines.append(re.sub(patt, sub, line))
                        break
                else:
                    raise Exception(f"ERROR: Not supported Perl line: [{i}: {line}]")
        return ''.join(lines)

    def _set_min_range_for_moc_ids(self, pddb_dict):
        for moc in pddb_dict['PDDB']:
            moc_index_param = pddb_dict['PDDB_TOPO'][moc]['index']
            moc_index_param_range = pddb_dict['PDDB'][moc][moc_index_param]['range']
            min_val, _max_val = moc_index_param_range.split('...')
            pddb_dict['PDDB'][moc][moc_index_param]['range'] = int(min_val)

    def _update_default_values_by_wtrans(self, pddb_dict):
        for moc in pddb_dict['PDDB']:
            for param in pddb_dict['PDDB'][moc]:
                h_param = pddb_dict['PDDB'][moc][param]
                if h_param['type'] == 'Structure':
                    for subparam in pddb_dict['PDDB'][moc][param]['struct']:
                        h_subparam = pddb_dict['PDDB'][moc][param]['struct'][subparam]
                        h_subparam['default'] = self._transform_by_wtrans(h_subparam['default'], h_subparam['wtrans'])
                else:
                    h_param['default'] = self._transform_by_wtrans(h_param['default'], h_param['wtrans'])

    def _transform_by_wtrans(self, value, wtrans):
        if value == '':
            return value

        wtrans_srch = re.search(r'return (.*\$in.*);', wtrans)
        if wtrans_srch:
            wtrans_sub = re.sub(r'\$in', value, wtrans_srch.group(1))
            new_value = str(round(eval(wtrans_sub), 5))
            new_value = re.sub(r'\.0+$', '', new_value)
            value = new_value
        return value

    def check_range(self, param, param_dict):
        try:
            param_type = param_dict['type']
            if param_type in self.CHECK_RANGE:
                self.CHECK_RANGE[param_type](param_dict)
            else:
                self.error(f"Wrong type for {param}: {param_type}")
        except Exception as exc:
            self.error(f"Wrong range for {param}: {exc}")

    def _check_range_number(self, param_dict):
        range_value = param_dict['range']
        param_value_list = param_dict['default']
        wtrans = param_dict['wtrans']
        srch = re.search(r"^([-.0-9]+)\.\.\.([-.0-9]+).*step [-.0-9]+", range_value)
        if not isinstance(param_value_list, list):
            param_value_list = [param_value_list]
        if srch:
            for param_value in param_value_list:
                str_min, str_max = (srch.group(1), srch.group(2))
                str_min = self._transform_by_wtrans(str_min, wtrans)
                str_max = self._transform_by_wtrans(str_max, wtrans)
                if "." in str_min or "." in str_max:
                    dec_param_value = float(param_value)
                    dec_min = float(str_min)
                    dec_max = float(str_max)
                else:
                    dec_param_value = int(param_value)
                    dec_min = int(str_min)
                    dec_max = int(str_max)

                if dec_param_value < dec_min or dec_param_value > dec_max:
                    if 'special' in param_dict:
                        str_special = param_dict['special']
                        if "." in str_special:
                            dec_special = float(str_special)
                        else:
                            dec_special = int(str_special)
                        if dec_special != dec_param_value:
                            raise Exception(f"Wrong value(number-special): val={param_value}, min={str_min}, max={str_max}, special={str_special}")
                    else:
                        raise Exception(f"Wrong value(number): val={param_value}, min={str_min}, max={str_max}")
        else:
            raise Exception(f"Wrong range(number): {range_value}")

    def _check_range_string(self, param_dict):
        range_value = param_dict['range']
        param_value_list = param_dict['default']
        if not isinstance(param_value_list, list):
            param_value_list = [param_value_list]
        srch = re.search(r"^([0-9]+)\.\.\.([0-9]+) characters", range_value)
        if srch:
            for param_value in param_value_list:
                r_min, r_max = (int(srch.group(1)), int(srch.group(2)))
                if isinstance(param_value, list) or isinstance(param_value, tuple):
                    for param_value_item in param_value:
                        if len(param_value_item) < r_min or len(param_value_item) > r_max:
                            raise Exception(f"Wrong value(string-list): val={param_value}, min_len={r_min}, max_len={r_max}")
                else:
                    if len(param_value) < r_min or len(param_value) > r_max:
                        raise Exception(f"Wrong value(string): val={param_value}, min_len={r_min}, max_len={r_max}")
        else:
            raise Exception(f"Wrong range(string): {range_value}")

    def _check_range_boolean(self, param_dict):
        param_value_list = param_dict['default']
        if not isinstance(param_value_list, list):
            param_value_list = [param_value_list]
        for param_value in param_value_list:
            if param_value != "true" and param_value != "false":
                raise Exception(f"Wrong value(boolean): val={param_value}")

    def _check_range_bitmask(self, param_dict):
        wtrans = param_dict['wtrans']
        if wtrans != " return shift ":
            raise Exception(f"Wrong wtrans(bitmask): {wtrans}")

    def _check_range_enumeration(self, param_dict):
        range_value = param_dict['range']
        param_value = param_dict['default']
        wtrans = param_dict['wtrans']
        if wtrans != " return shift ":
            raise Exception(f"Wrong wtrans(enumeration): {wtrans}")
        values = range_value.split("),")
        for i, val in enumerate(values):
            if val[-1] != ")":
                values[i] += ")"
        values = [re.search(r"^(.*)\s\(\d+\)$", x).group(1) for x in values]
        if isinstance(param_value, list) or isinstance(param_value, tuple):
            for param_value_item in param_value:
                param_value_item = str(param_value_item)
                if param_value_item not in values:
                    raise Exception(f"Wrong value(enumeration-list): val={param_value_item}, values={values}")
        else:
            param_value = str(param_value)
            if param_value not in values:
                raise Exception(f"Wrong value(enumeration): val={param_value}, values={values}")

    def parse_pddb_file(self, filepath):
        logger.info(f"Parsing pddb file: {filepath}")
        from_perl_pddb = self._transform_perl_to_py(filepath)
        parsed_pddb = eval('{' + from_perl_pddb + '}')
        self._set_min_range_for_moc_ids(parsed_pddb)
        self._update_default_values_by_wtrans(parsed_pddb)
        self.parsed_pddb = parsed_pddb

    def merge_moc_mandatory_params(self, enb_params):
        pddb_params = deepcopy(self.parsed_pddb['PDDB'])
        for mo, param in enb_params.items():
            if not pddb_params.get(mo):
                logger.warning(f"{mo} not in PDDB")
                continue
            for param_name, param_value in param.items():
                if param_name not in pddb_params[mo]:
                    logger.warning(f"{mo}::{param_name} not in PDDB")
                    continue
                self.merge_moc_mandatory_params_value(pddb_params, mo, param_name, param_value)
        return pddb_params

    def merge_moc_mandatory_params_value(self, pddb_params, mo, param_name, param_value):
        try:
            if isinstance(param_value, list):
                for sub_param in param_value:
                    if isinstance(sub_param, dict):
                        for sub_param_name, sub_param_value in sub_param.items():
                            pddb_params[mo][param_name]['required'] = True
                            pddb_params[mo][param_name]['struct'][sub_param_name]['required'] = True
                            pddb_params[mo][param_name]['struct'][sub_param_name]['default'] = sub_param_value
                            self.check_range(f"{mo}::{param_name}::{sub_param_name}", pddb_params[mo][param_name]['struct'][sub_param_name])
                    else:
                        pddb_params[mo][param_name]['required'] = True
                        pddb_params[mo][param_name]['default'] = param_value
                        self.check_range(f"{mo}::{param_name}", pddb_params[mo][param_name])
                        break
            else:
                pddb_params[mo][param_name]['required'] = True
                pddb_params[mo][param_name]['default'] = param_value
                self.check_range(f"{mo}::{param_name}", pddb_params[mo][param_name])
        except Exception as exc:
            self.error(f"Cannot merge {mo}::{param_name}::{param_value}: {exc}")

    def get_pddb_params_copy(self):
        return deepcopy(self.parsed_pddb['PDDB'])

    def get_pddb_topology_copy(self):
        return deepcopy(self.parsed_pddb['PDDB_TOPO'])

    def get_pddb_classes(self):
        return self.parsed_pddb['CLASS_MAP'], self.parsed_pddb['CLASS_VER']

    def error(self, msg):
        logger.error(msg)
        if self.fail_on_error:
            raise Exception(msg)
        tl_update("param_value_out_of_range", 1, {"status": "failure", "exception": msg})
